    _watched[1] = amps.r;
    _watched[2] = watts.r;
    _watched[3] = hz.r;
    _watched[4] = grid_ok.r;
    set_inputs(_watched, 5);
    set_health_row(io.resolve_out<uint8_t>("prog_ac_local_watch"));
